<?php
declare(strict_types=1);
require dirname(__DIR__) . '/src/bootstrap.php';
use App\Core\Security; use App\Core\LocalState;
Security::requireAuth(); Security::startSession(); $stateStore = new LocalState(); $state = $stateStore->all(); $message = null; $error = null;
if ($_SERVER['REQUEST_METHOD'] === 'POST') {
    if (!Security::verifyCsrf($_POST['_csrf'] ?? null)) $error = 'Security token expired. Refresh and try again.';
    else try {
        $action = (string)($_POST['action'] ?? '');
        if ($action === 'preferences') {
            $state['settings']['currency'] = in_array($_POST['currency'] ?? '', ['USD','BDT','EUR','GBP'], true) ? $_POST['currency'] : 'USD';
            $state['settings']['timezone'] = in_array($_POST['timezone'] ?? '', ['UTC','Asia/Dhaka','Asia/Kolkata','America/New_York'], true) ? $_POST['timezone'] : 'UTC';
            $state['settings']['date_range'] = in_array($_POST['date_range'] ?? '', ['7','30','90'], true) ? $_POST['date_range'] : '7';
            $state['settings']['notifications'] = isset($_POST['notifications']); $message = 'Workspace preferences saved.';
        } elseif ($action === 'brand') {
            $name = trim((string)($_POST['brand_name'] ?? '')); if ($name === '' || strlen($name) > 60) throw new RuntimeException('Brand name must be 1–60 characters.');
            $state['brand']['name'] = $name;
            if (isset($_FILES['logo']) && $_FILES['logo']['error'] !== UPLOAD_ERR_NO_FILE) {
                if ($_FILES['logo']['error'] !== UPLOAD_ERR_OK || $_FILES['logo']['size'] > 2 * 1024 * 1024) throw new RuntimeException('Logo must be a valid image smaller than 2 MB.');
                $info = @getimagesize($_FILES['logo']['tmp_name']); $allowed = ['image/png' => 'png', 'image/jpeg' => 'jpeg', 'image/webp' => 'webp'];
                if (!$info || !isset($allowed[$info['mime']])) throw new RuntimeException('Use PNG, JPG or WebP format.');
                $state['brand']['logo'] = 'data:' . $info['mime'] . ';base64,' . base64_encode((string)file_get_contents($_FILES['logo']['tmp_name']));
            }
            if (isset($_POST['remove_logo'])) $state['brand']['logo'] = null; $message = 'Brand settings saved.';
        } elseif ($action === 'provider') {
            $provider = ($_POST['provider'] ?? '') === 'google' ? 'google' : 'meta';
            $state['providers'][$provider]['enabled'] = isset($_POST['enabled']); $key = $provider === 'google' ? 'customer_id' : 'account_id'; $state['providers'][$provider][$key] = trim((string)($_POST['account_id'] ?? '')); $message = ucfirst($provider) . ' connection settings saved. Credentials remain server-side only.';
        }
        $state['updated_at'] = date(DATE_ATOM); $stateStore->save($state); $state = $stateStore->all();
    } catch (Throwable $e) { $error = $e->getMessage(); }
}
function e(string $v): string { return htmlspecialchars($v, ENT_QUOTES, 'UTF-8'); }
$logoUrl = $state['brand']['logo'] ? '/media.php?v=' . rawurlencode((string)($state['updated_at'] ?? '1')) : null;
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Settings · Stratmark Adpilot</title><style>:root{--navy:#12243a;--ink:#172231;--muted:#718096;--line:#e7edf3;--canvas:#f6f8fb;--blue:#2864e8;--green:#15966b;--amber:#b87312}*{box-sizing:border-box}body{margin:0;background:var(--canvas);color:var(--ink);font:14px/1.5 system-ui}.shell{display:flex;min-height:100vh}.side{width:238px;background:var(--navy);color:#d8e1ec;padding:25px 15px}.brand{display:flex;align-items:center;gap:10px;color:#fff;font-weight:800;padding:0 12px 30px}.brand img{width:34px;height:34px;object-fit:contain;border-radius:9px;background:#fff}.mark{width:34px;height:34px;border-radius:9px;background:#4f8aff;display:grid;place-items:center}.nav a{display:block;color:#b8c7d9;text-decoration:none;padding:11px 13px;border-radius:8px;margin:3px 0}.nav a:hover,.nav a.active{background:#1e3856;color:#fff}.side-close,.menu-backdrop,.mobile-menu{display:none}.main{flex:1;min-width:0}.top{height:76px;background:#fff;border-bottom:1px solid var(--line);display:flex;align-items:center;justify-content:space-between;padding:0 34px}.top a{color:var(--blue);text-decoration:none}.content{max-width:1050px;margin:auto;padding:30px 34px}.eyebrow{color:var(--blue);font-size:11px;font-weight:800;text-transform:uppercase;letter-spacing:1px}.content h1{margin:5px 0;font-size:27px}.sub{color:var(--muted);margin:0 0 24px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:16px}.card{background:#fff;border:1px solid var(--line);border-radius:12px;padding:21px;box-shadow:0 8px 24px #162b460a}.card h2{font-size:15px;margin:0 0 5px}.card p{font-size:12px;color:var(--muted)}label{display:block;font-weight:700;font-size:12px;margin:15px 0 6px}input,select{width:100%;padding:11px;border:1px solid #dbe3ec;border-radius:7px;background:#fff;font:inherit}.check{display:flex;gap:8px;align-items:center}.check input{width:auto}.btn{display:inline-block;border:0;background:var(--blue);color:#fff;border-radius:7px;padding:10px 14px;font:inherit;font-weight:750;margin-top:17px;cursor:pointer}.btn.secondary{background:#edf3ff;color:var(--blue)}.preview{height:76px;width:76px;border-radius:12px;object-fit:contain;background:#f0f4f8;border:1px dashed #bfd0e2;padding:8px}.flash{padding:12px;border-radius:8px;font-size:12px;margin-bottom:17px}.ok{background:#e8f8f1;color:#137754}.err{background:#fff0f0;color:#b23c48}.lock{color:var(--amber);background:#fff5e5;padding:11px;border-radius:8px;font-size:12px;margin-top:15px}@media(max-width:650px){.shell{display:block}.side{position:fixed;z-index:20;inset:0 auto 0 0;width:270px;min-height:100vh;padding:25px 15px;transform:translateX(-105%);transition:transform .2s ease;box-shadow:12px 0 28px #0a1e3733}.side.open{transform:translateX(0)}.side-close{display:block;position:absolute;right:13px;top:18px;background:transparent;color:#b8c7d9;border:0;font-size:22px;padding:4px}.menu-backdrop{display:none}.menu-backdrop.open{display:block;position:fixed;z-index:10;inset:0;background:#0a192d6b}.mobile-menu{display:inline-block;background:transparent;border:0;color:var(--ink);font-size:20px;margin-right:8px;padding:2px 7px}.nav{display:block}.nav a:first-child{grid-column:auto}.top{height:62px;padding:0 16px}.top strong{display:flex;align-items:center}.content{padding:24px 15px}.grid{grid-template-columns:1fr}}
</style></head><body><div class="shell"><div class="menu-backdrop"></div><aside class="side"><button class="side-close" type="button" aria-label="Close menu">×</button><div class="brand"><?php if($logoUrl):?><img src="<?=e($logoUrl)?>" alt="Brand logo"><?php else:?><span class="mark">SA</span><?php endif;?><span><?=e($state['brand']['name'])?></span></div><nav class="nav"><div style="font-size:10px;text-transform:uppercase;letter-spacing:1px;color:#7188a3;padding:12px 13px 8px">Workspace</div><a href="/">▦ Overview</a><a href="/page.php?view=campaigns">◉ Campaigns</a><a href="/page.php?view=creatives">◌ Creatives</a><a href="/page.php?view=insights">⌁ Insights</a><div style="font-size:10px;text-transform:uppercase;letter-spacing:1px;color:#7188a3;padding:12px 13px 8px">Control</div><a href="/page.php?view=approvals">✓ Approvals</a><a href="/page.php?view=automations">↗ Automations</a><a href="/page.php?view=activity">≡ Activity log</a><div style="font-size:10px;text-transform:uppercase;letter-spacing:1px;color:#7188a3;padding:12px 13px 8px">Settings</div><a class="active" href="/settings.php">⚙ Workspace settings</a></nav></aside><main class="main"><header class="top"><strong><button class="mobile-menu" type="button" aria-label="Open menu" aria-expanded="false">☰</button>Workspace settings</strong><a href="/logout.php">Sign out</a></header><section class="content"><div class="eyebrow">Control center</div><h1>Make Adpilot yours</h1><p class="sub">Brand your workspace, set reporting preferences and prepare safe provider connections.</p><?php if($message):?><div class="flash ok"><?=e($message)?></div><?php endif;?><?php if($error):?><div class="flash err"><?=e($error)?></div><?php endif;?><div class="grid"><section class="card"><h2>Brand identity</h2><p>Upload your logo. It is served through an authenticated route and kept in local application storage.</p><form method="post" enctype="multipart/form-data"><input type="hidden" name="_csrf" value="<?=e(Security::csrf())?>"><input type="hidden" name="action" value="brand"><label>Workspace name</label><input name="brand_name" value="<?=e($state['brand']['name'])?>" maxlength="60" required><label>Custom logo</label><input type="file" name="logo" accept="image/png,image/jpeg,image/webp"><div style="margin-top:12px"><?php if($logoUrl):?><img class="preview" src="<?=e($logoUrl)?>" alt="Current logo"><label class="check"><input type="checkbox" name="remove_logo"> Remove current logo</label><?php else:?><div class="preview" style="display:grid;place-items:center;color:#8ca0b6;font-size:11px">No logo</div><?php endif;?></div><button class="btn" type="submit">Save brand</button></form></section><section class="card"><h2>Reporting preferences</h2><p>Used by dashboard calculations and scheduled reports.</p><form method="post"><input type="hidden" name="_csrf" value="<?=e(Security::csrf())?>"><input type="hidden" name="action" value="preferences"><label>Currency<select name="currency"><option <?=($state['settings']['currency']==='USD'?'selected':'')?>>USD</option><option <?=($state['settings']['currency']==='BDT'?'selected':'')?>>BDT</option><option <?=($state['settings']['currency']==='EUR'?'selected':'')?>>EUR</option><option <?=($state['settings']['currency']==='GBP'?'selected':'')?>>GBP</option></select></label><label>Timezone<select name="timezone"><?php foreach(['UTC','Asia/Dhaka','Asia/Kolkata','America/New_York'] as $z):?><option <?=($state['settings']['timezone']===$z?'selected':'')?>><?=e($z)?></option><?php endforeach;?></select></label><label>Date range<select name="date_range"><option value="7" <?=($state['settings']['date_range']==='7'?'selected':'')?>>Last 7 days</option><option value="30" <?=($state['settings']['date_range']==='30'?'selected':'')?>>Last 30 days</option><option value="90" <?=($state['settings']['date_range']==='90'?'selected':'')?>>Last 90 days</option></select></label><label class="check"><input type="checkbox" name="notifications" <?=($state['settings']['notifications']?'checked':'')?>> Daily report notifications</label><button class="btn" type="submit">Save preferences</button></form></section><section class="card"><h2>Meta connection</h2><p>1) Create a Meta read token in Meta Business settings. 2) Add it as <code>META_ACCESS_TOKEN</code> in the server `.env`. 3) Enter the ad account ID below, save, then run the sync cron or <code>php bin/sync.php</code>.</p><form method="post"><input type="hidden" name="_csrf" value="<?=e(Security::csrf())?>"><input type="hidden" name="action" value="provider"><input type="hidden" name="provider" value="meta"><label>Ad account ID</label><input name="account_id" value="<?=e($state['providers']['meta']['account_id'])?>" placeholder="act_123..."><label class="check"><input type="checkbox" name="enabled" <?=($state['providers']['meta']['enabled']?'checked':'')?>> Enable read-only sync</label><button class="btn" type="submit">Save Meta mapping</button></form><div class="lock">Live writes are disabled by design.</div></section><section class="card"><h2>Google Ads connection</h2><p>1) Add a valid Google Ads OAuth access token as <code>GOOGLE_ACCESS_TOKEN</code> and developer token as <code>GOOGLE_DEVELOPER_TOKEN</code> in `.env`. 2) Enter the customer ID below. 3) Run <code>php bin/sync.php</code>. Keep read-only mode enabled.</p><form method="post"><input type="hidden" name="_csrf" value="<?=e(Security::csrf())?>"><input type="hidden" name="action" value="provider"><input type="hidden" name="provider" value="google"><label>Customer ID</label><input name="account_id" value="<?=e($state['providers']['google']['customer_id'])?>" placeholder="123-456-7890"><label class="check"><input type="checkbox" name="enabled" <?=($state['providers']['google']['enabled']?'checked':'')?>> Enable read-only sync</label><button class="btn" type="submit">Save Google mapping</button></form><div class="lock">Live writes are disabled by design.</div></section></div></section></main></div><script>(function(){const side=document.querySelector('.side'),open=document.querySelector('.mobile-menu'),close=document.querySelector('.side-close'),backdrop=document.querySelector('.menu-backdrop');function setMenu(value){side?.classList.toggle('open',value);backdrop?.classList.toggle('open',value);open?.setAttribute('aria-expanded',value?'true':'false')}open?.addEventListener('click',()=>setMenu(true));close?.addEventListener('click',()=>setMenu(false));backdrop?.addEventListener('click',()=>setMenu(false));document.querySelectorAll('.nav a').forEach(link=>link.addEventListener('click',()=>setMenu(false)));document.addEventListener('keydown',event=>{if(event.key==='Escape')setMenu(false)});})();</script></body></html>
